use std::{fs,path::Path};
#[derive(Clone)]pub struct Shipment{pub batch:u64,pub lane:String,pub lot:String,pub dest:String,pub ts:u64,pub temp:i64}
#[derive(Clone)]pub struct Sensor{pub seq:u64,pub lot:String,pub status:String}
pub fn shipments(root:&Path)->Result<Vec<Shipment>,String>{let mut out=Vec::new();for name in ["north.csv","south.csv","ambient.csv"]{let p=root.join("routes").join(name);let raw=fs::read_to_string(&p).map_err(|e|format!("read {}: {e}",p.display()))?;for line in raw.lines().skip(1).filter(|l|!l.trim().is_empty()){let c:Vec<&str>=line.split(',').collect(); if c.len()!=6{return Err(format!("bad row {}",p.display()))} out.push(Shipment{batch:c[0].parse().map_err(|_|"bad batch".to_string())?,lane:c[1].into(),lot:c[2].into(),dest:c[3].into(),ts:c[4].parse().map_err(|_|"bad ts".to_string())?,temp:c[5].parse().map_err(|_|"bad temp".to_string())?});}}Ok(out)}
pub fn sensors(root:&Path)->Result<Vec<Sensor>,String>{let mut out=Vec::new();for name in ["dock_a.csv","dock_b.csv","dock_c.csv"]{let p=root.join("sensors").join(name);let raw=fs::read_to_string(&p).map_err(|e|format!("read {}: {e}",p.display()))?;for line in raw.lines().skip(1).filter(|l|!l.trim().is_empty()){let c:Vec<&str>=line.split(',').collect(); if c.len()!=5{return Err(format!("bad row {}",p.display()))} out.push(Sensor{seq:c[0].parse().map_err(|_|"bad seq".to_string())?,lot:c[1].into(),status:c[4].into()});}}Ok(out)}
